import type {ShortArt, ShortBeat, ShortData} from '../compositions/Short';
import {LINE_WINDOWS, SHORT09_CAPTIONS, SHORT09_TOTAL_SEC} from './short09_timing';

/**
 * SHORT #9 — Timbs v. Indiana ("They can take your property without convicting you").
 * US-market English (the channel is US English; matches short06/07/08).
 * Source of truth: episodes/_planning/SHORTS_EP9-15.md (VO/telop) — Vote 9-0 / Excessive Fines / 2019.
 *
 * NARRATION-DRIVEN: cuts laid against the real narration line windows (short09_timing.ts,
 * generated by scripts/build_short09_mix.py). Same footage for YouTube and TikTok; only CTA differs.
 */

const img = (n: string) => `shorts/short09/short09_${n}.png`;
const r3 = (n: number) => Math.round(n * 1000) / 1000;

type Cut = {
  line: string;
  id: string;
  src: string | null;
  kind: 'image' | 'video' | 'card';
  motion: ShortBeat['motion'];
  telop?: string;
  fast?: boolean;
  art?: ShortArt;
};

const CUTS: Cut[] = [
  // L1 — hook: civil forfeiture can take your property without a conviction
  {line: 'L1', id: 'hook', src: img('01'), kind: 'image', motion: 'pushin', fast: true,
   telop: 'TAKEN WITHOUT\nA CONVICTION', art: {kind: 'bignum', top: 'NO', bottom: 'CONVICTION'}},
  // L2 — a $42k SUV bought with his late father's life insurance
  {line: 'L2', id: 'b1', src: img('02'), kind: 'image', motion: 'kenburns', telop: "BOUGHT WITH HIS\nDAD'S INSURANCE"},
  {line: 'L2', id: 'b1b', src: img('03'), kind: 'image', motion: 'parallax'},
  // L3 — seized over a small drug sale: about 4x the maximum fine
  {line: 'L3', id: 'b2a', src: img('04'), kind: 'image', motion: 'kenburns',
   telop: '4× THE MAX FINE', art: {kind: 'bignum', top: '4×', bottom: 'THE MAX FINE'}},
  {line: 'L3', id: 'b2b', src: img('05'), kind: 'image', motion: 'pushin'},
  // L4 — climax: 2019 SCOTUS 9-0, excessive fines applies to states; he got the car back
  {line: 'L4', id: 'c1', src: img('06'), kind: 'image', motion: 'kenburns',
   telop: '2019: 9-0\nEXCESSIVE FINES', art: {kind: 'vote', yes: 9, no: 0}},
  {line: 'L4', id: 'c2', src: img('07'), kind: 'image', motion: 'pushin',
   art: {kind: 'citation', label: 'Timbs v. Indiana', source: '2019'}},
  {line: 'L4', id: 'c3', src: img('07'), kind: 'image', motion: 'parallax', telop: 'HE GOT HIS\nCAR BACK'},
  // L5 — CTA (platform-specific endcard text swapped at export)
  {line: 'L5', id: 'cta', src: img('01'), kind: 'image', motion: 'kenburns'},
];

/** Lay each line's cuts continuously across [line.start, nextLine.start) (last -> total). */
const buildBeats = (): ShortBeat[] => {
  const beats: ShortBeat[] = [];
  LINE_WINDOWS.forEach((win, i) => {
    const spanStart = win.start;
    const spanEnd = i + 1 < LINE_WINDOWS.length ? LINE_WINDOWS[i + 1].start : SHORT09_TOTAL_SEC;
    const cuts = CUTS.filter((c) => c.line === win.id);
    const each = (spanEnd - spanStart) / Math.max(1, cuts.length);
    cuts.forEach((cut, k) => {
      const {line: _line, ...rest} = cut;
      beats.push({...rest, startSec: r3(spanStart + k * each), durSec: r3(each)});
    });
  });
  return beats;
};

export const SHORT09: ShortData = {
  shortId: 'short09',
  episodeId: 'PD-2026-009-timbs',
  durationSec: SHORT09_TOTAL_SEC,
  narrationSrc: 'shorts/short09/audio/short09_final_mix_v002_en_us.mp3', // full 4-layer mix
  captions: SHORT09_CAPTIONS,
  bgmSrc: null, // BGM/ambience/SFX already inside the mix
  ctaTextYT: 'Watch on YouTube',
  ctaTextTT: 'Full episode on our profile',
  beats: buildBeats(),
};
